#!/usr/bin/env python3
"""
NL-to-SQL Analytics Copilot - Self-extracting setup script.

HOW TO USE:
  1. Download this file (setup_project.py)
  2. Open a terminal in the same folder
  3. Run:  python setup_project.py
  4. This creates a folder "nl-to-sql-copilot" with all project files
  5. Then run:
     cd nl-to-sql-copilot
     git init
     git add .
     git commit -m "Initial commit"
     git remote add origin https://github.com/Vasu618/nl_to_sql_copilot.git
     git branch -M main
     git push -u origin main
"""
import base64, tarfile, io, os

TARBALL_B64 = ""

def main():
    print("Extracting project files...")
    data = base64.b64decode(TARBALL_B64)
    tar = tarfile.open(fileobj=io.BytesIO(data))
    members = tar.getmembers()
    tar.extractall("nl-to-sql-copilot")
    tar.close()
    print(f"Done! Extracted {len(members)} files to nl-to-sql-copilot/")
    print()
    print("Next steps:")
    print("  cd nl-to-sql-copilot")
    print("  git init")
    print("  git add .")
    print('  git commit -m "Initial commit"')
    print("  git remote add origin https://github.com/Vasu618/nl_to_sql_copilot.git")
    print("  git branch -M main")
    print("  git push -u origin main")

if __name__ == "__main__":
    main()
